FAQS = [["What is Nano Banana 2.1?","Nano Banana 2.1 is Google's high-efficiency Gemini image-generation and conversational editing model, an upgrade from Gemini 3.1 Flash Image (Nano Banana 2). It targets faster, more affordable production with stronger text rendering, multi-turn consistency and 1K–4K images."],["What is the Nano Banana 2.1 API model ID?","Use gemini-nano-banana-2.1 in the Gemini Interactions API or compatible Google GenAI SDK. It is different from gemini-3.1-flash-image (Nano Banana 2) and gemini-3-pro-image (Nano Banana Pro)."],["How much does Nano Banana 2.1 cost per generated image?","Google's Standard paid API output estimates are $0.0336 per 1K image, $0.0504 per 2K image and $0.113 per 4K image. Input tokens, text/thinking output and optional Google Search grounding are charged separately."],["How much does Nano Banana 2.1 Batch cost?","Google lists Batch image-output estimates of $0.0168 per 1K image, $0.0252 per 2K image and $0.0567 per 4K image. Batch is asynchronous, and non-image request costs still apply."],["Is Nano Banana 2.1 free in the Gemini API?","The official Gemini Nano Banana 2.1 pricing table lists no free API tier. Access through Google AI Studio or a consumer app follows separate availability and usage conditions."],["Does Nano Banana 2.1 generate 4K images?","Yes. It supports 1K (default), 2K and 4K image-output tiers. Google documents a 4096×4096 4K square and 5504×3072 4K 16:9 output, as well as wider panoramic ratios."],["How many reference images can Nano Banana 2.1 use?","Google documents up to 14 input reference images, with fidelity guidance for up to 10 objects and consistency across up to 4 characters in a workflow. Those are not guarantees of perfect identity reproduction."],["Can Nano Banana 2.1 edit existing images?","Yes. Supply image content and an edit request through the Gemini API, then make additional changes in a multi-turn workflow. Explicitly state what to alter and which identities, shapes, colors or words to preserve."],["Which thinking levels does Nano Banana 2.1 support?","It supports minimal, medium and high thinking levels, with medium as the documented default. Greater thinking can increase latency or token usage and does not guarantee a flawless output."],["Does Nano Banana 2.1 support Google Image Search grounding?","Yes. Google documents web_search and image_search as search_types for its google_search tool, allowing the model to incorporate current web and image context. Grounded visual facts and licensing must still be reviewed."],["What is the difference between Nano Banana 2, 2.1 and Pro?","Nano Banana 2.1 is Google's recommended newer high-efficiency production model; Nano Banana 2 is the previous Gemini 3.1 Flash Image endpoint; Nano Banana Pro uses gemini-3-pro-image for more demanding professional visual tasks. Each has different pricing and capabilities."],["What inputs can Nano Banana 2.1 accept?","The official model card lists text, images, video and PDF input, with text and image output. A 131,072-token input limit and 32,768-token output limit are published, but those limits are not image pixel dimensions."],["Can I use Nano Banana 2.1 for logos, labels and infographics?","It supports advanced text rendering, diagram layout and branded image editing, but generated spelling, trademarks, data labels and chart values must be checked manually before production use."],["Does Nano Banana 2.1 watermark images?","Google says Nano Banana generated images include an invisible SynthID watermark. The watermark does not replace rights clearance, image review or any required AI-content disclosure."]]
SECTIONS = "\n        <section class=\"model-deep-section\" id=\"nb21-overview\" data-nano-banana-21-guide>\n          <div class=\"model-section-head\"><p class=\"eyebrow\">MODEL OVERVIEW</p><h2>What is Nano Banana 2.1?</h2></div>\n          <p><strong>Nano Banana 2.1</strong> is Google's high-efficiency model for <strong>AI image generation and conversational image editing</strong>. Its exact Gemini API ID is <code>gemini-nano-banana-2.1</code>. Google calls it the newer production workhorse compared with Nano Banana 2 (Gemini 3.1 Flash Image), with improved realism, text rendering, prompt adherence, multi-turn character consistency and Google Search grounding. It is the more cost-efficient counterpart to <a href=\"/models/gemini-3-pro-image/\">Nano Banana Pro</a>.</p>\n          <p><strong>Quick answer:</strong> output at <strong>1K, 2K or 4K</strong> (1K default), work with <strong>up to 14 reference images</strong>, configure thinking (<code>minimal</code>, <code>medium</code>, <code>high</code>), and ground requests with Google Web and Image Search. Official Standard API image-output estimates start at <strong>$0.0336 for 1K</strong>. Input and thinking costs are separate. <a href=\"https://ai.google.dev/gemini-api/docs/models/gemini-nano-banana-2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Google documents these capabilities in its model card</a>.</p>\n          <nav class=\"model-related-links\" aria-label=\"Nano Banana 2.1 reference sections\">\n            <a href=\"#nb21-pricing\"><span>OFFICIAL PRICING</span><strong>1K, 2K, 4K and Batch</strong><b>↗</b></a>\n            <a href=\"#nb21-api\"><span>GEMINI API</span><strong>Code examples and model ID</strong><b>↗</b></a>\n            <a href=\"#nb21-comparisons\"><span>MODEL COMPARISON</span><strong>Nano Banana 2 vs 2.1 vs Pro</strong><b>↗</b></a>\n          </nav>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"nb21-specs\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">OFFICIAL MODEL SPECIFICATIONS</p><h2>Nano Banana 2.1 specifications and capabilities.</h2></div>\n          <div class=\"model-capability-grid\">\n            <article><span>GEMINI API MODEL ID</span><h3><code>gemini-nano-banana-2.1</code></h3><p>Provider-native ID, not the same as <code>gemini-3.1-flash-image</code> or <code>gemini-3-pro-image</code>.</p></article>\n            <article><span>IMAGE OUTPUT</span><h3>1K / 2K / 4K</h3><p>The image size is a separate control from aspect ratio. The default output tier is 1K; 0.5K is not a documented output tier for 2.1.</p></article>\n            <article><span>IMAGE REFERENCE INPUT</span><h3>Up to 14 images</h3><p>Model guidance includes up to 10 object references at high fidelity and up to 4 character references for consistency.</p></article>\n            <article><span>MULTIMODAL INPUT</span><h3>Text · image · video · PDF</h3><p>Supported inputs as listed by Google; outputs are text and images. Video input does not imply video-generation output.</p></article>\n            <article><span>CONTEXT AND OUTPUT LIMIT</span><h3>131,072 / 32,768 tokens</h3><p>Maximum published input and output token counts, not the output image pixel size or image price.</p></article>\n            <article><span>THINKING CONTROLS</span><h3>Minimal / medium / high</h3><p>Default <code>medium</code>; select a level appropriate for quality, latency and cost instead of assuming higher is always better.</p></article>\n            <article><span>GROUNDING</span><h3>Google Web + Image Search</h3><p>Search-grounded context helps with current visual subjects. Search requests may be billed separately; outputs need factual review.</p></article>\n            <article><span>PRODUCTION MODE</span><h3>Standard + Batch</h3><p>Batch has lower published image-output rates but is asynchronous. No free developer API tier is listed in the provider price table.</p></article>\n          </div>\n          <p>Model capabilities and limits come from the <a href=\"https://ai.google.dev/gemini-api/docs/models/gemini-nano-banana-2.1\" target=\"_blank\" rel=\"noopener noreferrer\">official Google model card</a>. Avoid confusing multimodal input support with video generation, or image-token output rates with text-output rates.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"nb21-pricing\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">GEMINI API PRICING</p><h2>Nano Banana 2.1 price per image: Standard, Batch and hidden costs.</h2></div>\n          <p>Google's paid Standard API rate for generated <strong>image output is $30 per one million image tokens</strong>, equivalent to its published estimates below. Input text/images/video are <strong>$1.50 per million tokens</strong>, while text and thinking output are <strong>$7.50 per million tokens</strong>. Those are three distinct meters; never use the image-output rate to price textual output.</p>\n          <div class=\"model-capability-grid\">\n            <article><span>STANDARD · 1K</span><h3>$0.0336 / image</h3><p>Google's estimated generated-image output charge at 1K. Does not include request input or extra output.</p></article>\n            <article><span>STANDARD · 2K</span><h3>$0.0504 / image</h3><p>Estimated output charge at 2K; suitable for evaluating image detail versus cost.</p></article>\n            <article><span>STANDARD · 4K</span><h3>$0.113 / image</h3><p>Google's published 4K image output estimate, excluding input and optional grounding.</p></article>\n            <article><span>BATCH · 1K</span><h3>$0.0168 / image</h3><p>Approximate image-output cost on asynchronous Batch jobs; request costs remain additional.</p></article>\n            <article><span>BATCH · 2K</span><h3>$0.0252 / image</h3><p>Lower image-output price for scheduled/high-volume workloads.</p></article>\n            <article><span>BATCH · 4K</span><h3>$0.0567 / image</h3><p>Published Batch output estimate at 4K, with the same caveat for separate non-image billing.</p></article>\n          </div>\n          <p><strong>Production budget example:</strong> 100 Standard 1K image outputs cost about <strong>$3.36</strong> in image-output fees; 100 Standard 4K outputs cost about <strong>$11.30</strong>. For Batch, comparable output fees are about <strong>$1.68</strong> and <strong>$5.67</strong>. These are not complete request bills: prompts, image/video references, text/thinking output and chargeable searches may increase totals.</p>\n          <p><strong>Grounding rate:</strong> Google lists 5,000 free Web/Image Search grounding requests monthly, shared across Gemini 3 and newer models, followed by $14 per 1,000 requests. The API free tier for the model itself is <strong>not available</strong>. Check the latest <a href=\"https://ai.google.dev/gemini-api/docs/pricing\" target=\"_blank\" rel=\"noopener noreferrer\">Google Gemini API pricing schedule</a> before production cost estimates.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"nb21-formats\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">IMAGE OUTPUT AND FORMATS</p><h2>Nano Banana 2.1 resolution and aspect-ratio examples.</h2></div>\n          <p>Google documents square, portrait, landscape and extra-wide options, including <strong>1:1, 4:5, 9:16, 16:9, 21:9</strong> and panoramic <strong>1:4, 4:1, 1:8, 8:1</strong>. For Nano Banana 2.1, Google reports fixes for image-tiling artifacts at 2K and 4K in these extra-wide compositions.</p>\n          <div class=\"model-capability-grid\">\n            <article><span>1:1 SQUARE</span><h3>1024 → 2048 → 4096 px</h3><p>Square image sizes at 1K, 2K and 4K tiers. Good for ecommerce thumbnails and product grids.</p></article>\n            <article><span>16:9 LANDSCAPE</span><h3>1376×768 → 5504×3072</h3><p>Published 1K-to-4K range for wide hero assets; 2K is 2752×1536.</p></article>\n            <article><span>9:16 PORTRAIT</span><h3>768×1376 → 3072×5504</h3><p>Vertical publishing and mobile campaigns; 2K is 1536×2752.</p></article>\n            <article><span>21:9 ULTRAWIDE</span><h3>1584×672 → 6336×2688</h3><p>Panoramic banners; 2K is 3168×1344.</p></article>\n            <article><span>4:5 PORTRAIT</span><h3>928×1152 → 3712×4608</h3><p>Portrait social and product layouts; 2K is 1856×2304.</p></article>\n            <article><span>1:8 BANNER</span><h3>384×3072 → 1536×12288</h3><p>Unusual long compositions. Test content and crop behavior; better aspect handling does not mean every detail will be perfect.</p></article>\n          </div>\n          <p>Google's <a href=\"https://ai.google.dev/gemini-api/docs/image-generation\" target=\"_blank\" rel=\"noopener noreferrer\">Nano Banana image-size tables</a> give the precise dimensions for all 14 documented aspect ratios. A 4K tier is not always 4096 pixels on every axis.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"nb21-editing\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">IMAGE CREATION AND EDITING</p><h2>Nano Banana 2.1 text-to-image and conversational image editing.</h2></div>\n          <div class=\"model-capability-grid\">\n            <article><span>TEXT TO IMAGE</span><h3>Turn a prompt into a scene</h3><p>Specify the subject, composition, camera angle, materials, lighting, aspect ratio and any text that must appear. Try multiple alternatives at 1K, then use 2K or 4K for the final layout.</p><p><strong>Example prompt:</strong> “Create a clean 4:5 product photograph of a matte black travel bottle on sandstone, side-lit at golden hour. Minimal pale background. Label text exactly ‘NORTH’. Realistic contact shadow.”</p></article>\n            <article><span>CONVERSATIONAL EDITING</span><h3>Make precise follow-up changes</h3><p>Provide an input image, request a new background, remove a distracting object or change clothing while preserving identity. Multi-turn revisions work best when you distinguish new changes from elements that must remain.</p><p><strong>Example edit:</strong> “Keep the product shape, brand color and label unchanged. Replace the desk with a sunny kitchen counter. Preserve camera angle and perspective.”</p></article>\n            <article><span>OBJECT AND CHARACTER REFERENCES</span><h3>Combine multiple image sources</h3><p>Supply references for products, people and style; explicitly assign roles by image number. Google lists up to 14 references overall, with distinct object/character fidelity guidance.</p><p><strong>Example:</strong> “Place the chair from image 1 in the room from image 2, apply the texture in image 3, and retain the seated person's clothing from image 4.”</p></article>\n            <article><span>DESIGN WITH TEXT</span><h3>Layouts, localization and charts</h3><p>Google highlights improved text rendering and infographic layout. Use exact quoted text and verify letters, translations, axes, numbers and any legal claims before publishing.</p></article>\n          </div>\n          <p>These example prompts are editorial illustrations of the model's documented workflows, not provider-certified quality benchmarks. Read Google's <a href=\"https://ai.google.dev/gemini-api/docs/image-generation\" target=\"_blank\" rel=\"noopener noreferrer\">multi-turn editing and multi-image guide</a> for input formatting.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"nb21-api\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">GEMINI DEVELOPER API</p><h2>How to use Nano Banana 2.1: REST API example.</h2></div>\n          <p>Send requests to Google's <strong>Gemini Interactions API</strong> with model ID <code>gemini-nano-banana-2.1</code>. The example below asks for a <strong>2K landscape image</strong> with the documented <code>response_format</code> object. Configure your <code>GEMINI_API_KEY</code> on the server; do not expose it in client-side JavaScript.</p>\n          <pre style=\"white-space:pre-wrap;overflow-wrap:anywhere;overflow-x:auto\"><code>curl -s -X POST \\\n  \"https://generativelanguage.googleapis.com/v1beta/interactions\" \\\n  -H \"x-goog-api-key: $GEMINI_API_KEY\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\n    \"model\": \"gemini-nano-banana-2.1\",\n    \"input\": \"A photorealistic editorial kitchen scene with a copper kettle, soft morning light and natural shadows.\",\n    \"response_format\": {\n      \"type\": \"image\",\n      \"aspect_ratio\": \"16:9\",\n      \"image_size\": \"2K\"\n    }\n  }'</code></pre>\n          <div class=\"model-caveat-list\">\n            <div><span>01</span><p><strong>Image generation:</strong> request <code>gemini-nano-banana-2.1</code>, set image size and aspect ratio, and read the image data returned by the Interactions API or SDK.</p></div>\n            <div><span>02</span><p><strong>Image editing:</strong> send image and text input blocks together to request an edit. Preserve the previous interaction context for follow-up edits when appropriate.</p></div>\n            <div><span>03</span><p><strong>Google Search grounding:</strong> optionally add <code>\"tools\": [{\"type\": \"google_search\", \"search_types\": [\"web_search\", \"image_search\"]}]</code>. Budget for any billable search usage and verify licensing of source content.</p></div>\n            <div><span>04</span><p><strong>Mixed output:</strong> when requesting images plus explanatory text, process all content blocks. Do not assume every response uses only one image or that generated text is always correct.</p></div>\n          </div>\n          <p>Copy the current request shape and SDK patterns from the <a href=\"https://ai.google.dev/gemini-api/docs/image-generation\" target=\"_blank\" rel=\"noopener noreferrer\">Google Interactions API image-generation examples</a>. The older <code>generateContent</code> request and response formats differ and should not be mixed into the same example.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"nb21-grounding\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">DISTINCTIVE IMAGE FEATURES</p><h2>Thinking levels, Google Image Search and SynthID.</h2></div>\n          <div class=\"model-capability-grid\">\n            <article><span>THINKING CONFIGURATION</span><h3>Minimal · medium · high</h3><p>Google lists medium as default. Choose minimal for simpler tasks and evaluate higher reasoning for difficult design constraints; measure cost and latency on your own workload.</p></article>\n            <article><span>GROUNDING WITH WEB SEARCH</span><h3>Current contextual information</h3><p>Can use search results to inform an image about recent topics. Generated weather, diagrams or market visualizations can still mislabel facts, so verify numbers.</p></article>\n            <article><span>GROUNDING WITH IMAGE SEARCH</span><h3>Image-aware search context</h3><p>Specify <code>image_search</code> in Google's search tool. Google notes current limitations for using real-world people's photos retrieved from web search.</p></article>\n            <article><span>PROVENANCE</span><h3>Invisible SynthID</h3><p>Google states Nano Banana output carries SynthID watermarking. This does not replace checking rights to reference images or disclosure requirements.</p></article>\n          </div>\n          <p><strong>Important:</strong> Search grounding is a research aid, not an accuracy guarantee. Do not publish an image as proof of a factual claim without checking the cited original source.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"nb21-comparisons\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">MODEL CHOICE</p><h2>Nano Banana 2.1 vs Nano Banana 2, Pro and FLUX.2 Max.</h2></div>\n          <div class=\"model-capability-grid\">\n            <article><span>BEST FOR EFFICIENT PRODUCTION</span><h3>Nano Banana 2.1</h3><p>Google's newer high-efficiency workhorse with up to 14 references, 1K–4K output and Search grounding. Standard image-output estimates start at $0.0336.</p></article>\n            <article><span>PREVIOUS WORKHORSE</span><h3><a href=\"/models/gemini-3-1-flash-image/\">Nano Banana 2</a></h3><p>Gemini 3.1 Flash Image, distinct API ID and prices. Google recommends Nano Banana 2.1 for new projects instead of the previous-generation endpoint.</p></article>\n            <article><span>PREMIUM GOOGLE OPTION</span><h3><a href=\"/models/gemini-3-pro-image/\">Nano Banana Pro</a></h3><p>Optimized for complex professional visual assets, deeper creative control and advanced localization. Official Standard image-output estimate: $0.134 for 1K/2K and $0.24 at 4K.</p></article>\n            <article><span>ALTERNATIVE PRICING MODEL</span><h3><a href=\"/models/flux-2-max/\">FLUX.2 Max</a></h3><p>Black Forest Labs uses megapixel-based pricing with separate reference input charges. Compare generated images under similar prompt constraints instead of ranking on price alone.</p></article>\n          </div>\n          <p><strong>Direct comparison:</strong> at the Standard 1K output tier, Nano Banana 2.1's published image-output estimate is <strong>$0.0336</strong>, versus <strong>$0.134</strong> for Nano Banana Pro (both excluding non-image charges). Nano Banana 2.1 costs less on this metric; it does not establish universal superiority in image quality.</p>\n          <p>Read the focused comparisons: <a href=\"/compare/nano-banana-2-vs-nano-banana-2-1/\">Nano Banana 2 vs 2.1</a> and <a href=\"/compare/nano-banana-2-1-vs-nano-banana-pro/\">Nano Banana 2.1 vs Pro</a>.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"nb21-prompts\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">PRODUCTION PROMPTING</p><h2>Prompts and workflow tips for better Nano Banana 2.1 results.</h2></div>\n          <div class=\"model-caveat-list\">\n            <div><span>01</span><p><strong>Write a complete creative brief:</strong> start with subject, environment, framing, materials and lighting, then specify what the image is for.</p></div>\n            <div><span>02</span><p><strong>Give visible text explicitly:</strong> quote the exact headline, label or call-to-action. Recheck spelling, brand marks and font consistency.</p></div>\n            <div><span>03</span><p><strong>Assign roles to references:</strong> say which image supplies the product, person, color palette and scene. Avoid relying on the model to infer source priority.</p></div>\n            <div><span>04</span><p><strong>Separate edits from invariants:</strong> state what should change and what must remain fixed (identity, product geometry, original logo, text placement).</p></div>\n            <div><span>05</span><p><strong>Test 1K before 4K:</strong> choose size according to delivery needs and estimate both image-output and non-image costs. Large size is not a substitute for good composition.</p></div>\n            <div><span>06</span><p><strong>Review data-backed visuals:</strong> audit numerical charts, factual map details, third-party marks and any grounded search-derived material.</p></div>\n          </div>\n          <p>These are practical editorial recommendations, not guarantees of precise reproduction. Google's model card reports improvements to text layout and panoramic tiling; production results still depend on prompts and reference quality.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"nb21-use-cases\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">WHERE IT FITS</p><h2>Best Nano Banana 2.1 use cases, strengths and limitations.</h2></div>\n          <div class=\"model-capability-grid\">\n            <article><span>ECOMMERCE</span><h3>Iterative product photography</h3><p>Explore multiple lifestyle backgrounds around a consistent product reference without paying a premium for every first draft.</p></article>\n            <article><span>SOCIAL AND BRAND DESIGN</span><h3>Text-heavy image layouts</h3><p>Draft ads, visual posts and localized graphic assets; confirm small text and brand compliance before distribution.</p></article>\n            <article><span>CREATIVE OPERATIONS</span><h3>Repeatable multi-turn editing</h3><p>Make controlled edits over successive rounds with consistent characters or objects using reference images and clear constraints.</p></article>\n            <article><span>EDITORIAL GRAPHICS</span><h3>Search-informed illustration</h3><p>Combine current contextual information and visual prompting for explainers, with an explicit fact-checking step.</p></article>\n          </div>\n          <p><strong>Limits:</strong> outputs are images and text, not generated video. The API has no free tier according to Google's pricing page, thinking and grounding can add costs, and generated facts, charts, logos and text require human verification. The hosted model is not an open-weights self-hosted release.</p>\n        </section>\n\n        <section class=\"model-deep-section\" id=\"nb21-related\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">RELATED REFERENCE PAGES</p><h2>Explore Google image models and verified comparisons.</h2></div>\n          <div class=\"model-related-links\">\n            <a href=\"/models/gemini-3-1-flash-image/\"><span>PREVIOUS GENERATION</span><strong>Nano Banana 2 model specs</strong><b>↗</b></a>\n            <a href=\"/models/gemini-3-pro-image/\"><span>PREMIUM IMAGE GENERATION</span><strong>Nano Banana Pro API &amp; pricing</strong><b>↗</b></a>\n            <a href=\"/models/flux-2-max/\"><span>OTHER IMAGE PROVIDER</span><strong>FLUX.2 Max model reference</strong><b>↗</b></a>\n            <a href=\"/compare/nano-banana-2-vs-nano-banana-2-1/\"><span>VERSION DIFFERENCES</span><strong>Nano Banana 2 vs 2.1</strong><b>↗</b></a>\n            <a href=\"/compare/nano-banana-2-1-vs-nano-banana-pro/\"><span>GOOGLE IMAGE COMPARISON</span><strong>Nano Banana 2.1 vs Pro</strong><b>↗</b></a>\n            <a href=\"/providers/google/\"><span>ALL GOOGLE MODELS</span><strong>Google provider directory</strong><b>↗</b></a>\n            <a href=\"/models/pricing/\"><span>ALL PRICING</span><strong>Verified AI model pricing</strong><b>↗</b></a>\n          </div>\n        </section>\n"
FAQ_HTML = "\n        <section class=\"model-deep-section\" id=\"nb21-faq\">\n          <div class=\"model-section-head\"><p class=\"eyebrow\">NANO BANANA 2.1 FAQ</p><h2>Questions about prices, 4K images, API and editing.</h2></div>\n          <div class=\"model-caveat-list\">\n            <div><span>01</span><p><strong>What is Nano Banana 2.1?</strong> Nano Banana 2.1 is Google's high-efficiency Gemini image-generation and conversational editing model, an upgrade from Gemini 3.1 Flash Image (Nano Banana 2). It targets faster, more affordable production with stronger text rendering, multi-turn consistency and 1K–4K images.</p></div>\n            <div><span>02</span><p><strong>What is the Nano Banana 2.1 API model ID?</strong> Use gemini-nano-banana-2.1 in the Gemini Interactions API or compatible Google GenAI SDK. It is different from gemini-3.1-flash-image (Nano Banana 2) and gemini-3-pro-image (Nano Banana Pro).</p></div>\n            <div><span>03</span><p><strong>How much does Nano Banana 2.1 cost per generated image?</strong> Google's Standard paid API output estimates are $0.0336 per 1K image, $0.0504 per 2K image and $0.113 per 4K image. Input tokens, text/thinking output and optional Google Search grounding are charged separately.</p></div>\n            <div><span>04</span><p><strong>How much does Nano Banana 2.1 Batch cost?</strong> Google lists Batch image-output estimates of $0.0168 per 1K image, $0.0252 per 2K image and $0.0567 per 4K image. Batch is asynchronous, and non-image request costs still apply.</p></div>\n            <div><span>05</span><p><strong>Is Nano Banana 2.1 free in the Gemini API?</strong> The official Gemini Nano Banana 2.1 pricing table lists no free API tier. Access through Google AI Studio or a consumer app follows separate availability and usage conditions.</p></div>\n            <div><span>06</span><p><strong>Does Nano Banana 2.1 generate 4K images?</strong> Yes. It supports 1K (default), 2K and 4K image-output tiers. Google documents a 4096×4096 4K square and 5504×3072 4K 16:9 output, as well as wider panoramic ratios.</p></div>\n            <div><span>07</span><p><strong>How many reference images can Nano Banana 2.1 use?</strong> Google documents up to 14 input reference images, with fidelity guidance for up to 10 objects and consistency across up to 4 characters in a workflow. Those are not guarantees of perfect identity reproduction.</p></div>\n            <div><span>08</span><p><strong>Can Nano Banana 2.1 edit existing images?</strong> Yes. Supply image content and an edit request through the Gemini API, then make additional changes in a multi-turn workflow. Explicitly state what to alter and which identities, shapes, colors or words to preserve.</p></div>\n            <div><span>09</span><p><strong>Which thinking levels does Nano Banana 2.1 support?</strong> It supports minimal, medium and high thinking levels, with medium as the documented default. Greater thinking can increase latency or token usage and does not guarantee a flawless output.</p></div>\n            <div><span>10</span><p><strong>Does Nano Banana 2.1 support Google Image Search grounding?</strong> Yes. Google documents web_search and image_search as search_types for its google_search tool, allowing the model to incorporate current web and image context. Grounded visual facts and licensing must still be reviewed.</p></div>\n            <div><span>11</span><p><strong>What is the difference between Nano Banana 2, 2.1 and Pro?</strong> Nano Banana 2.1 is Google's recommended newer high-efficiency production model; Nano Banana 2 is the previous Gemini 3.1 Flash Image endpoint; Nano Banana Pro uses gemini-3-pro-image for more demanding professional visual tasks. Each has different pricing and capabilities.</p></div>\n            <div><span>12</span><p><strong>What inputs can Nano Banana 2.1 accept?</strong> The official model card lists text, images, video and PDF input, with text and image output. A 131,072-token input limit and 32,768-token output limit are published, but those limits are not image pixel dimensions.</p></div>\n            <div><span>13</span><p><strong>Can I use Nano Banana 2.1 for logos, labels and infographics?</strong> It supports advanced text rendering, diagram layout and branded image editing, but generated spelling, trademarks, data labels and chart values must be checked manually before production use.</p></div>\n            <div><span>14</span><p><strong>Does Nano Banana 2.1 watermark images?</strong> Google says Nano Banana generated images include an invisible SynthID watermark. The watermark does not replace rights clearance, image review or any required AI-content disclosure.</p></div>\n          </div>\n        </section>\n"
SOURCES = ["https://ai.google.dev/gemini-api/docs/models/gemini-nano-banana-2.1","https://ai.google.dev/gemini-api/docs/pricing","https://ai.google.dev/gemini-api/docs/image-generation"]

_CAVEATS = '<section class="model-deep-section"><div class="model-section-head"><p class="eyebrow">CAVEATS</p>'


def _once(page, before, after):
    if page.count(before) != 1:
        raise ValueError("Nano Banana 2.1 template changed: " + before[:60])
    return page.replace(before, after, 1)


def _meta(page, name, text):
    pattern = r'(<meta (?:name|property)="' + re.escape(name) + r'" content=")[^"]*(" />)'
    new, count = re.subn(
        pattern,
        lambda match: match.group(1) + escape(text, quote=True) + match.group(2),
        page, count=1,
    )
    if count != 1:
        raise ValueError("Nano Banana 2.1 expected metadata missing: " + name)
    return new


def enrich_nano_banana_21_page(page):
    """Keep existing TechArticle and breadcrumb, enrich visible model facts and schema."""
    if 'data-nano-banana-21-guide' in page:
        return page
    if f'<link rel="canonical" href="{CANONICAL}"' not in page:
        raise ValueError("Nano Banana 2.1 canonical URL changed")

    page, count = re.subn(r"<title>.*?</title>", "<title>" + escape(TITLE) + "</title>", page, count=1)
    if count != 1:
        raise ValueError("Nano Banana 2.1 missing HTML title")
    for name, content in (
        ("description", DESCRIPTION),
        ("og:title", TITLE),
        ("og:description", DESCRIPTION),
        ("twitter:title", TITLE),
        ("twitter:description", DESCRIPTION),
    ):
        page = _meta(page, name, content)

    replacements = [
        ('<h1>Nano Banana 2.1<br><span>verified model reference.</span></h1>',
         "<h1>Nano Banana 2.1<br><span>Image generation, 4K &amp; API pricing.</span></h1>"),
        ('<p>Google&#x27;s efficient production image creation and conversational editing model with 1K, 2K and 4K output and improved text rendering, references and character consistency.</p>',
         "<p>" + escape(HERO) + "</p>"),
        ('<div><strong>131,072</strong><span>context tokens</span></div>',
         '<div><strong>1K–4K</strong><span>image output tiers</span></div>'),
        ('<div><strong>32,768</strong><span>max output</span></div>',
         '<div><strong>14</strong><span>reference images supported</span></div>'),
        ('<div><span>STANDARD INPUT</span><strong>$1.50</strong><small>per 1 million tokens (IMAGE output; text output billed separately)</small></div>',
         '<div><span>INPUT TOKENS</span><strong>$1.50</strong><small>Standard per million text/image/video tokens</small></div>'),
        ('<div><span>STANDARD OUTPUT</span><strong>$30.00</strong><small>per 1 million tokens (IMAGE output; text output billed separately)</small></div>',
         '<div><span>IMAGE OUTPUT</span><strong>$30.00</strong><small>Standard per million IMAGE tokens; text/thinking output priced separately</small></div>'),
        ('<article><span>REASONING</span><h3>minimal · medium · high · default medium</h3><p>Only provider-documented reasoning controls are shown; missing controls remain unpublished rather than inferred.</p></article>',
         '<article><span>THINKING LEVELS</span><h3>minimal · medium · high</h3><p>Default medium. Choose based on creative difficulty, cost and latency; Google documents these three levels for 2.1.</p></article>'),
        ('<p>SXF preserves the provider-published native billing basis. Only calculator-eligible generative token models enter token-cost arithmetic; specialist units and input-only embeddings remain visible without forced conversion.</p>',
         '<p>The listed $30 output rate applies to IMAGE tokens, while text/thinking output is $7.50 per million tokens. Image-output cost depends on 1K, 2K or 4K tier, with separate input and grounding charges. See the detailed prices below.</p>'),
    ]
    for old, new in replacements:
        page = _once(page, old, new)

    script_match = re.search(r'(<script type="application/ld\+json">)(.*?)(</script>)', page, re.DOTALL)
    if not script_match:
        raise ValueError("Nano Banana 2.1 JSON-LD missing")
    data = json.loads(script_match.group(2))
    if data.get("@context") != "https://schema.org":
        raise ValueError("Nano Banana 2.1 JSON-LD context missing")
    nodes = data["@graph"]
    article = next((n for n in nodes if n.get("@type") == "TechArticle"), None)
    crumb = next((n for n in nodes if n.get("@type") == "BreadcrumbList"), None)
    if article is None or crumb is None:
        raise ValueError("Nano Banana 2.1 article or breadcrumbs missing")
    article.update({
        "headline": TITLE.removesuffix(" | SXF / AI"),
        "description": DESCRIPTION,
        "citation": SOURCES,
        "mainEntityOfPage": {"@id": CANONICAL},
        "author": {"@id": "https://sxf.si/#organization"},
        "publisher": {"@id": "https://sxf.si/#organization"},
        "about": {
            "@type": "Thing",
            "name": "Nano Banana 2.1",
            "alternateName": ["Gemini Nano Banana 2.1"],
            "identifier": "gemini-nano-banana-2.1",
            "sameAs": SOURCES[0],
        },
        "keywords": [
            "Nano Banana 2.1", "Gemini Nano Banana 2.1",
            "Nano Banana 2.1 pricing", "Nano Banana 2.1 API",
            "Nano Banana 2.1 4K", "Nano Banana 2.1 image editing",
        ],
    })
    crumb["@id"] = CANONICAL + "#breadcrumb"
    nodes.insert(0, {
        "@type": "WebPage",
        "@id": CANONICAL,
        "url": CANONICAL,
        "name": TITLE.removesuffix(" | SXF / AI"),
        "description": DESCRIPTION,
        "inLanguage": "en",
        "mainEntity": {"@id": CANONICAL + "#article"},
        "breadcrumb": {"@id": CANONICAL + "#breadcrumb"},
        "isPartOf": {"@id": "https://sxf.si/#website"},
    })
    nodes.append({
        "@type": "WebSite",
        "@id": "https://sxf.si/#website",
        "name": "SXF / AI",
        "url": "https://sxf.si/",
        "publisher": {"@id": "https://sxf.si/#organization"},
    })
    nodes.append({
        "@type": "Organization",
        "@id": "https://sxf.si/#organization",
        "name": "SXF / AI",
        "url": "https://sxf.si/",
    })
    nodes.append({
        "@type": "FAQPage",
        "@id": CANONICAL + "#faq",
        "url": CANONICAL + "#nb21-faq",
        "inLanguage": "en",
        "mainEntity": [
            {
                "@type": "Question", "name": question,
                "acceptedAnswer": {"@type": "Answer", "text": answer},
            }
            for question, answer in FAQS
        ],
    })
    encoded = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
    page = page[:script_match.start(2)] + encoded + page[script_match.end(2):]
    return _once(page, _CAVEATS, SECTIONS + FAQ_HTML + "\n\n        " + _CAVEATS)
